//! Binding admission metadata kept beside the original native scroll packet.

use flui_foundation::InputSequenceId;
use flui_platform_api::pointer::{DeviceId, PointerKind, ScrollEvent, ScrollPhase};

/// Why a logical scroll delta was produced.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum ScrollCause {
    /// Direct contact, wheel, keyboard or assistive input.
    UserInput,
    /// Inertia generated by the platform.
    Momentum,
    /// Framework-generated motion, including a fling.
    SideEffect,
    /// An application command or a reveal request.
    Programmatic,
}

/// The actual source of an admitted scrolling sequence.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum ScrollDevice {
    /// Pointer input; an absent backend identity remains explicitly unknown.
    Pointer {
        /// Backend-provided device kind.
        kind: PointerKind,
        /// Backend-provided device identity, when available.
        device: Option<DeviceId>,
    },
    /// Focused keyboard input.
    Keyboard,
    /// An assistive-technology action.
    Assistive,
    /// An application-owned operation.
    Programmatic,
}

/// Why an admitted sequence no longer owns scrolling.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum ScrollEndReason {
    /// The source ended normally, including contactless inactivity.
    Released,
    /// The source or its presentation was cancelled.
    Cancelled,
    /// A newer input sequence replaced this one.
    Preempted,
    /// The contact lost gesture ownership.
    ArenaLost,
}

/// Completion delivered to the exact consumer selected by a native stream.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub struct ScrollSequenceEnd {
    /// The identity previously delivered with the stream's deltas.
    pub sequence: InputSequenceId,
    /// The committed reason for withdrawing that identity.
    pub reason: ScrollEndReason,
}

/// Delta or completion on one selected scroll target.
///
/// Completion carries no synthetic native event or invented zero delta.
#[derive(Debug, Clone, Copy)]
#[non_exhaustive]
pub enum ScrollSignal<'a> {
    /// A localized native packet, including a possible final delta.
    Delta(ScrollDispatch<'a>),
    /// The binding has withdrawn this stream before invoking the callback.
    End(ScrollSequenceEnd),
}

/// A scroll packet localized to one target, retaining its admitted source.
///
/// Read `local` for target coordinates and `global` for presentation coordinates.
/// Binding identity is absent for standalone raw dispatch; those callers must
/// not invent a pointer label as a sequence identity.
#[derive(Debug, Clone, Copy)]
#[non_exhaustive]
pub struct ScrollDispatch<'a> {
    /// The receiving target's local packet.
    pub local: &'a ScrollEvent,
    /// The original packet in root coordinates.
    pub global: &'a ScrollEvent,
    /// Binding-owned identity, including repeated packets in the same stream.
    pub sequence: Option<InputSequenceId>,
    /// Explicit platform inertia versus direct user input.
    pub cause: ScrollCause,
}

impl<'a> ScrollDispatch<'a> {
    /// Describes an honest standalone dispatch without binding admission.
    #[must_use]
    pub fn at_root(event: &'a ScrollEvent) -> Self {
        Self {
            local: event,
            global: event,
            sequence: None,
            cause: if matches!(
                event.phase,
                Some(
                    ScrollPhase::MomentumBegan
                        | ScrollPhase::MomentumChanged
                        | ScrollPhase::MomentumEnded
                )
            ) {
                ScrollCause::Momentum
            } else {
                ScrollCause::UserInput
            },
        }
    }

    pub(crate) fn admitted(event: &'a ScrollEvent, sequence: InputSequenceId) -> Self {
        Self {
            sequence: Some(sequence),
            ..Self::at_root(event)
        }
    }

    pub(crate) fn localized(self, local: &'a ScrollEvent) -> Self {
        Self { local, ..self }
    }

    /// Backend source metadata from the original packet.
    #[must_use]
    pub fn device(self) -> ScrollDevice {
        ScrollDevice::Pointer {
            kind: self.global.pointer.kind,
            device: self.global.pointer.device,
        }
    }
}
